import {languages,messages} from './i18n.js?v=20261002-final';
import {dishes,categories,ingredientKeys,storeInfo,recommendations,recommendedMenuIds,filterDishes} from './data.js?v=20261002-final';
import {icons} from './icons.js?v=20261002-final';
const app=document.querySelector('#app'),dialog=document.querySelector('#detail');
const state={lang:'en',chosen:false,page:'menu',avoid:[],spice:null,spiceMode:'exact',category:'all',country:'all',selected:null,dialogMode:'detail',filtersOpen:false};
let lastFocus=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>messages[state.lang][k]??messages.en[k]??k;
const icon=k=>icons[k]??'';
const recommendedIds=new Set(recommendedMenuIds);
const recommendedLabel=()=>({en:'Recommended',ja:'おすすめ','zh-Hans':'推荐'})[state.lang];
const recommendationBadge=d=>recommendedIds.has(d.id)?`<span class="recommendation-badge">${icon('star')}<span>${recommendedLabel()}</span></span>`:'';
const info=k=>storeInfo.find(x=>x.key===k)?.[state.lang]??'';
const spice=d=>d.spiceLevel===null?t('unknownSpice'):t(['notSpicy','mild','spicy'][d.spiceLevel]);
const availableAvoidKeys=new Set(ingredientKeys.filter(k=>dishes.some(d=>d.ingredients[k]==='absent_verified')));
const visibleDishes=()=>filterDishes(dishes,state,{recs:state.country==='all'?null:recommendations.filter(r=>r.countryCode===state.country)});
const spiceBadge=d=>`<p class="spice spice-${d.spiceLevel}">${d.spiceLevel>0?`<span class="spice-peppers" aria-hidden="true">${icon('pepper').repeat(d.spiceLevel)}</span>`:''}<span>${esc(spice(d))}</span></p>`;
const languageButtons=()=>`<div class="language-buttons" role="group" aria-label="${t('chooseLanguage')}">${Object.entries(languages).map(([k,v])=>`<button data-lang="${k}" lang="${k}" aria-pressed="${state.lang===k}">${v}</button>`).join('')}</div>`;
function picture(d,large=false){return d.photo?`<button class="food-photo ${large?'large':''}" data-photo="${d.id}" aria-label="${esc(t('zoom')+' · '+d.names[state.lang])}"><img src="${d.photo}" alt="${esc(d.names[state.lang])}" width="1280" height="960" ${d.id==='M006'?'fetchpriority="high"':'loading="lazy"'}><span class="zoom-mark">${icon('zoom')}</span></button>`:`<div class="photo-missing">${icon('photo')}<span>${esc(t('photoPending'))}</span></div>`;}
function ingredients(d){return `<div class="ingredients-block"><p class="eyebrow">${esc(t('ingredients'))}</p>${d.contains.length?`<ul class="ingredient-icons">${d.contains.map(k=>`<li>${icon(k)}<span>${esc(t(k))}</span></li>`).join('')}</ul>`:`<p class="muted">${esc(t('unknown'))}</p>`}</div>`;}
function card(d){return `<article class="dish" id="dish-${d.id}"><div class="dish-heading"><span class="menu-number">${d.menuNumber}</span><div><h3 class="dish-title">${recommendationBadge(d)}<span>${esc(d.names[state.lang])}</span></h3><p class="korean" lang="ko">${esc(d.nameKo)}</p></div></div><div class="dish-layout">${picture(d)}<div class="dish-information"><div class="price-row"><strong class="price">₩${d.priceKrw.toLocaleString('en-US')}</strong><span>${esc(d.units[state.lang])}</span></div><p class="description">${esc(d.descriptions[state.lang])}</p>${d.seasonal?`<p class="seasonal">${esc(t('seasonal'))} · ${esc(t('seasonNote'))}</p>`:''}${ingredients(d)}${!['dessert','drinks'].includes(d.categoryId)?spiceBadge(d):''}${d.wheatOption?`<p class="option-note">${esc(t('wheatOption'))}</p>`:''}<button class="detail-button" data-detail="${d.id}">${esc(t('details'))}</button></div></div></article>`;}
function filters(){return `<details class="filter-panel" ${state.filtersOpen?'open':''}><summary>${icon('filter')}${esc(t('filters'))}</summary><div class="filter-body"><fieldset><legend>${esc(t('avoid'))}</legend><div class="filter-chips">${ingredientKeys.map(k=>`<button data-avoid="${k}" ${availableAvoidKeys.has(k)?'':'disabled'} aria-pressed="${state.avoid.includes(k)}">${esc(t(k))}</button>`).join('')}</div><p class="muted">${esc(t(availableAvoidKeys.size?'filterHelp':'ingredientUnavailable'))}</p></fieldset><div class="selects"><label>${esc(t('spice'))}<select id="spice">${[['',t('anySpice')],['0',t('notSpicy')],['1',t(state.spiceMode==='exact'?'mild':'upMild')],['2',t(state.spiceMode==='exact'?'spicy':'spicyMax')]].map(([v,s])=>`<option value="${v}" ${(state.spice===null?'':String(state.spice))===v?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>${esc(t('recommendations'))}<select id="country">${['all','JP','VN','MN'].map(k=>`<option value="${k}" ${state.country===k?'selected':''}>${esc(t(k))}</option>`).join('')}</select></label></div><button data-reset class="text-button">${esc(t('reset'))}</button></div></details>`;}
function menu(){const list=visibleDishes();return `<div class="menu-tools">${filters()}<p class="filter-results" role="status" aria-live="polite">${esc(t('results').replace('{count}',list.length))}</p><p class="ingredient-note">${esc(t('ingredientNote'))}</p></div><div class="menu-sections">${categories.map((c,i)=>{const items=list.filter(d=>d.categoryId===c);return items.length?`<section class="menu-section" id="category-${c}" aria-labelledby="heading-${c}"><div class="section-heading"><span>${String(i+1).padStart(2,'0')}</span><h2 id="heading-${c}">${esc(t(c))}</h2><span class="section-count">${items.length}</span></div>${items.map(card).join('')}</section>`:'';}).join('')}${!list.length?`<div class="empty"><h2>${esc(t('noResults'))}</h2><p>${esc(t('noResultsHelp'))}</p><button data-reset>${esc(t('reset'))}</button></div>`:''}</div>`;}
function information(){const keys=state.page==='how'?['order','delivery','self','return','changes']:['intro','hours'];return `<div class="information-page"><p class="eyebrow">GAYOUNGENE</p><h1>${esc(t(state.page))}</h1>${keys.map((k,i)=>`<section class="information-block"><span class="info-number">${String(i+1).padStart(2,'0')}</span><div><h2>${esc(t(k))}</h2><p>${esc(info(k))}</p></div></section>`).join('')}</div>`;}
function render(){document.documentElement.lang=state.lang;document.querySelector('.skip').textContent=t('skip');app.innerHTML=`<header class="site-header"><a href="#" class="brand" data-home aria-label="Gayoungene"><img src="./assets/gayoungene-logo.png" alt="가영이네 Gayoungene" width="1417" height="502"></a><div class="header-tools"><span class="brand-sub">MENU GUIDE</span>${languageButtons()}</div></header>${!state.chosen?`<section class="language-welcome"><div><p class="eyebrow">WELCOME TO GAYOUNGENE</p><h1>Choose your language</h1><p lang="ja">言語を選択 <span aria-hidden="true">·</span> <span lang="zh-Hans">请选择语言</span></p></div>${languageButtons()}</section>`:''}<nav class="primary-nav" aria-label="Gayoungene">${['menu','how','visit'].map(k=>`<button data-page="${k}" ${state.page===k?'aria-current="page"':''}>${esc(t(k))}</button>`).join('')}</nav><div class="site-layout ${state.page!=='menu'?'info-layout':''}">${state.page==='menu'?`<aside class="category-nav"><details id="category-menu" ${matchMedia('(min-width:900px)').matches?'open':''}><summary>${esc(t('categories'))}${icon('down')}</summary><div class="category-links">${categories.map((c,i)=>visibleDishes().some(d=>d.categoryId===c)?`<a href="#category-${c}" data-category="${c}"><span>${String(i+1).padStart(2,'0')}</span>${esc(t(c))}</a>`:'').join('')}</div></details></aside>`:''}<main id="main">${state.page==='menu'?menu():information()}</main></div><footer><img src="./assets/gayoungene-logo.png" alt="Gayoungene" width="1417" height="502"><p>${esc(t('translationNote'))}</p><a href="./icon-credits.txt">Icon credits</a></footer>`;document.querySelector('.filter-panel')?.addEventListener('toggle',e=>{if(e.target.isConnected)state.filtersOpen=e.target.open;});}
function renderDialog(){const d=dishes.find(x=>x.id===state.selected);if(!d)return;const zoom=state.dialogMode==='photo',staff=state.dialogMode==='staff';dialog.className=zoom?'photo-dialog':'';dialog.innerHTML=`<div class="dialog-top">${languageButtons()}<button data-close class="close-button" aria-label="${esc(t('close'))}">${icon('close')}</button></div><div class="dialog-body"><p class="eyebrow">MENU ${d.menuNumber}</p><h2 id="detail-title" class="dish-title">${recommendationBadge(d)}<span>${esc(staff?d.nameKo:d.names[state.lang])}</span></h2><p class="korean" lang="${staff?state.lang:'ko'}">${esc(staff?d.names[state.lang]:d.nameKo)}</p>${zoom?`<img class="expanded-photo" src="${d.photo}" alt="${esc(d.names[state.lang])}">`:staff?`<p>${esc(t('staffNote'))}</p>`:`${ingredients(d)}<p class="ingredient-note">${esc(t('ingredientNote'))}</p><h3>${esc(t('moreIngredients'))}</h3><p>${esc(t('pending'))}</p>${d.otherMeat?`<p>${esc(t('otherMeat'))}</p>`:''}${d.wheatOption?`<p>${esc(t('wheatOption'))}</p>`:''}<dl class="ingredient-status">${ingredientKeys.map(k=>`<div><dt>${esc(t(k))}</dt><dd>${esc(t(d.ingredients[k]))}</dd></div>`).join('')}</dl><p>${esc(info('changes'))}</p><button class="primary-button" data-staff>${esc(t('showStaff'))}</button>`}</div>`;}
function openDish(id,mode){if(!dishes.some(d=>d.id===id))return;lastFocus=document.activeElement;state.selected=id;state.dialogMode=mode;renderDialog();dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('[data-close]').focus();const u=new URL(location.href);u.searchParams.set('menu',id);history.replaceState(null,'',u);}
function closeDialog(){const id=state.selected;dialog.close();document.body.style.overflow='';state.selected=null;const u=new URL(location.href);u.searchParams.delete('menu');history.replaceState(null,'',u);const trigger=lastFocus?.isConnected?lastFocus:document.querySelector(lastFocus?.dataset.photo?'[data-photo="'+id+'"]':'[data-detail="'+id+'"]');trigger?.focus({preventScroll:true});}
function changeLanguage(lang){if(!languages[lang])return;const y=scrollY;state.lang=lang;state.chosen=true;render();if(dialog.open){renderDialog();dialog.querySelector('[data-lang="'+lang+'"]')?.focus();}window.scrollTo(0,y);}
function reset(){state.filtersOpen=true;state.avoid=[];state.spice=null;state.spiceMode='exact';state.country='all';state.category='all';render();}
app.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.hasAttribute('data-home')){e.preventDefault();state.page='menu';render();window.scrollTo(0,0);}else if(el.dataset.lang)changeLanguage(el.dataset.lang);else if(el.dataset.page){state.page=el.dataset.page;render();window.scrollTo(0,0);}else if(el.dataset.category){e.preventDefault();const d=document.querySelector('#category-menu');if(d&&!matchMedia('(min-width:900px)').matches)d.open=false;document.querySelector('#category-'+el.dataset.category)?.scrollIntoView({behavior:'smooth',block:'start'});}else if(el.dataset.photo)openDish(el.dataset.photo,'photo');else if(el.dataset.detail)openDish(el.dataset.detail,'detail');else if(el.dataset.avoid){const k=el.dataset.avoid;if(!availableAvoidKeys.has(k))return;state.avoid=state.avoid.includes(k)?state.avoid.filter(v=>v!==k):[...state.avoid,k];state.filtersOpen=true;const y=scrollY;render();document.querySelector('[data-avoid="'+k+'"]').focus({preventScroll:true});scrollTo(0,y);}else if(el.hasAttribute('data-reset'))reset();});
app.addEventListener('change',e=>{if(!['spice','country'].includes(e.target.id))return;state.filtersOpen=true;if(e.target.id==='spice'){state.spice=e.target.value===''?null:Number(e.target.value);state.spiceMode='exact';}if(e.target.id==='country')state.country=e.target.value;const id=e.target.id,y=scrollY;render();document.getElementById(id)?.focus({preventScroll:true});scrollTo(0,y);});
dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lang)changeLanguage(b.dataset.lang);if(b.hasAttribute('data-close'))closeDialog();if(b.hasAttribute('data-staff')){state.dialogMode='staff';renderDialog();dialog.scrollTop=0;dialog.querySelector('[data-close]').focus();}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
render();const initial=new URL(location.href).searchParams.get('menu');if(initial){const d=dishes.find(d=>d.id===initial||d.menuNumber===initial);if(d)openDish(d.id,'detail');}
// Optional browser integration shares the exact same verified-ingredient filter.
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'configure_menu_filters',description:'Filter menu items. Unconfirmed ingredient absences are excluded. Does not place orders.',inputSchema:{type:'object',properties:{avoid:{type:'array',items:{type:'string',enum:ingredientKeys}},maxSpice:{type:['integer','null'],minimum:0,maximum:2}},required:['avoid','maxSpice'],additionalProperties:false},execute(input){if(!input||!Array.isArray(input.avoid)||input.avoid.some(k=>!ingredientKeys.includes(k))||![null,0,1,2].includes(input.maxSpice))throw Error('Invalid filters');state.avoid=[...new Set(input.avoid)];state.spice=input.maxSpice;state.spiceMode='max';state.page='menu';state.filtersOpen=true;render();return {items:visibleDishes().map(d=>({id:d.id,name:d.names[state.lang]}))};}});}catch{}}
